window.AUTH=window.AUTH||{};window.AUTH["86-228"]={"d":"86-228","id":"1986/86-228","n":"Kungys v. United States","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the United States on reargument","date":"","url":"https://www.justice.gov/osg/media/219391/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/juozas-kungys-petitioner-v-united-states-america-0","toa":false,"n":15},{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/205506/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/juozas-kungys-petitioner-v-united-states-america","toa":false,"n":61}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep485/usrep485759/usrep485759.pdf","tr":false,"items":[{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Luria v. United States","cite":"231 U.S. 9","y":1913,"id":"scdb/1913-058","sc":1,"sum":"Where a point involving sufficiency of the complaint is not raised and defendant does not challenge the statement of the court that it supposes the point will not be raised, it is too late to raise it in this court.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Kairys","cite":"782 F.2d 1374","url":"https://www.courtlistener.com/c/F.2d/782/1374/","by":{"0":"","1":""}},{"t":"case","label":"Costello v. United States","cite":"365 U.S. 265","y":1961,"id":"1960/59","sc":1,"op":3,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Fedorenko v. United States","cite":"449 U.S. 490","y":1981,"id":"1980/79-5602","sc":1,"op":25,"sum":"The Displaced Persons Act of 1948 (DPA) enabled European refugees driven from their homelands by World War II to emigrate to the United States without regard to traditional immigration quotas. It provided that any person \"who shall willfully make a misrepresentation for the purpose of gaining admission into the United States as an eligible displaced person shall thereafter not be admissible into the United States,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Stevens v. United States","cite":"190 F.2d 880","y":1951,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/190/880/","by":{"0":""}},{"t":"case","label":"United States v. Harrison","cite":"180 F.2d 981","y":1950,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/180/981/","by":{"0":""}},{"t":"case","label":"Del Guercio v. Pupko","cite":"160 F.2d 799","y":1947,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/160/799/","by":{"0":""}},{"t":"case","label":"United States v. Forrest","cite":"69 F. Supp. 389","y":1946,"court":"D.R.I.","url":"https://www.courtlistener.com/c/F.%20Supp./69/389/","by":{"0":"","1":""}},{"t":"case","label":"Even the Tenth Circuit in United States v. Sheshtawy","cite":"714 F.2d 1038","y":1983,"url":"https://www.courtlistener.com/c/F.2d/714/1038/","op":3,"by":{"0":"","1":""}},{"t":"case","label":"Klapprott v. United States","cite":"335 U.S. 601","y":1949,"id":"scdb/1948-023","sc":1,"op":7,"sum":"The judgments are reversed and the cause is remanded to the district court with instructions to set aside the default judgment and grant petitioner a hearing on the merits of the issues raised by the denaturalization complaint. Pp. 602-608, 615-616. [This judgment modified, 336 U. S. 942.] 166 F. 2d 273, reversed. A federal district court entered a default judgment setting aside an order admitting petitioner to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Accardo","cite":"113 F. Supp. 783","url":"https://www.courtlistener.com/c/F.%20Supp./113/783/","by":{"0":"","1":""}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(f)(6)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"","1":""}},{"t":"usc","label":"8 U.S.C. § 1427","url":"https://www.law.cornell.edu/uscode/text/8/1427","subs":["(a)"],"stext":{"head":"§1427. Requirements of naturalization","paras":[[0,"(a) Residence"],[0,"No person, except as otherwise provided in this subchapter, shall be naturalized unless such applicant, (1) immediately preceding the date of filing his application for naturalization has resided continuously, after being lawfully admitted for permanent residence, within the United States for at least five years and during the five years immediately preceding the date of filing his application has been physically present therein for periods totaling at least half of that time, and who has resided within the State or within the district of the Service in the United States in which the applicant filed the application for at least three months, (2) has resided continuously within the United States from the date of the application up to the time of admission to citizenship, and (3) during all the periods referred to in this subsection has been and still is a person of good moral character, attached to the principles of the Constitution of the United States, and well disposed to the good order and happiness of the United States."],[0,"(b) Absences"],[0,"Absence from the United States of more than six months but less than one year during the period for which continuous residence is required for admission to citizenship, immediately preceding the date of filing the application for naturalization, or during the period between the date of filing the application and the date of any hearing under section 1447(a) of this title, shall break the continuity of such residence, unless the applicant shall establish to the satisfaction of the Attorney General that he did not in fact abandon his residence in the United States during such period."],[0,"Absence from the United States for a continuous period of one year or more during the period for which continuous residence is required for admission to citizenship (whether preceding or subsequent to the filing of the application for naturalization) shall break the continuity of such residence, except that in the case of a person who has been physically present and residing in the United States, after being lawfully admitted for permanent residence, for an uninterrupted period of at least one year, and who thereafter is employed by or under contract with the Government of the United States or an American institution of research recognized as such by the Attorney General, or is employed by an American firm or corporation engaged in whole or in part in the development of foreign trade and commerce of the United States, or a subsidiary thereof more than 50 per centum of whose stock is owned by an American firm or corporation, or is employed by a public international organization of which the United States is a member by treaty or statute and by which the alien was not employed until after being lawfully admitted for permanent residence, no period of absence from the United States shall break the continuity of residence if—"],[1,"(1) prior to the beginning of such period of employment (whether such period begins before or after his departure from the United States), but prior to the expiration of one year of continuous absence from the United States, the person has established to the satisfaction of the Attorney General that his absence from the United States for such period is to be on behalf of such Government, or for the purpose of carrying on scientific research on behalf of such institution, or to be engaged in the development of such foreign trade and commerce or whose residence abroad is necessary to the protection of the property rights in such countries in such firm or corporation, or to be employed by a public international organization of which the United States is a member by treaty or statute and by which the alien was not employed until after being lawfully admitted for permanent residence; and"],[1,"(2) such person proves to the satisfaction of the Attorney General that his absence from the United States for such period has been for such purpose."],[0,"The spouse and dependent unmarried sons and daughters who are members of the household of a person who qualifies for the benefits of this subsection shall also be entitled to such benefits during the period for which they were residing abroad as dependent members of the household of the person."],[0,"(c) Physical presence"],[0,"The granting of the benefits of subsection (b) of this section shall not relieve the applicant from the requirement of physical presence within the United States for the period specified in subsection (a) of this section, except in the case of those persons who are employed by, or under contract with, the Government of the United States. In the case of a person employed by or under contract with Central Intelligence Agency, the requirement in subsection (b) of an uninterrupted period of at least one year of physical presence in the United States may be complied with by such person at any time prior to filing an application for naturalization."],[0,"(d) Moral character"],[0,"No finding by the Attorney General that the applicant is not deportable shall be accepted as conclusive evidence of good moral character."],[0,"(e) Determination"],[0,"In determining whether the applicant has sustained the burden of establishing good moral character and the other qualifications for citizenship specified in subsection (a) of this section, the Attorney General shall not be limited to the applicant's conduct during the five years preceding the filing of the application, but may take into consideration as a basis for such determination the applicant's conduct and acts at any time prior to that period."],[0,"(f) Persons making extraordinary contributions to national security"],[0,"(1) Whenever the Director of Central Intelligence, the Attorney General and the Commissioner of Immigration determine that an applicant otherwise eligible for naturalization has made an extraordinary contribution to the national security of the United States or to the conduct of United States intelligence activities, the applicant may be naturalized without regard to the residence and physical presence requirements of this section, or to the prohibitions of section 1424 of this title, and no residence within a particular State or district of the Service in the United States shall be required: Provided, That the applicant has continuously resided in the United States for at least one year prior to naturalization: Provided further, That the provisions of this subsection shall not apply to any alien described in clauses (i) through (v) of section 1158(b)(2)(A) of this title."],[0,"(2) An applicant for naturalization under this subsection may be administered the oath of allegiance under section 1448(a) of this title by any district court of the United States, without regard to the residence of the applicant. Proceedings under this subsection shall be conducted in a manner consistent with the protection of intelligence sources, methods and activities."],[0,"(3) The number of aliens naturalized pursuant to this subsection in any fiscal year shall not exceed five. The Director of Central Intelligence shall inform the Select Committee on Intelligence and the Committee on the Judiciary of the Senate and the Permanent Select Committee on Intelligence and the Committee on the Judiciary of the House of Representatives within a reasonable time prior to the filing of each application under the provisions of this subsection."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1427?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1427. Requirements of naturalization","tname":"Aliens and Nationality","by":{"0":"","1":""}},{"t":"usc","label":"8 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/8/1451","subs":["(a)"],"stext":{"head":"§1451. Revocation of naturalization","paras":[[0,"(a) Concealment of material evidence; refusal to testify"],[0,"It shall be the duty of the United States attorneys for the respective districts, upon affidavit showing good cause therefor, to institute proceedings in any district court of the United States in the judicial district in which the naturalized citizen may reside at the time of bringing suit, for the purpose of revoking and setting aside the order admitting such person to citizenship and canceling the certificate of naturalization on the ground that such order and certificate of naturalization were illegally procured or were procured by concealment of a material fact or by willful misrepresentation, and such revocation and setting aside of the order admitting such person to citizenship and such canceling of certificate of naturalization shall be effective as of the original date of the order and certificate, respectively: Provided, That refusal on the part of a naturalized citizen within a period of ten years following his naturalization to testify as a witness in any proceeding before a congressional committee concerning his subversive activities, in a case where such person has been convicted of contempt for such refusal, shall be held to constitute a ground for revocation of such person's naturalization under this subsection as having been procured by concealment of a material fact or by willful misrepresentation. If the naturalized citizen does not reside in any judicial district in the United States at the time of bringing such suit, the proceedings may be instituted in the United States District Court for the District of Columbia or in the United States district court in the judicial district in which such person last had his residence."],[0,"(b) Notice to party"],[0,"The party to whom was granted the naturalization alleged to have been illegally procured or procured by concealment of a material fact or by willful misrepresentation shall, in any such proceedings under subsection (a) of this section, have sixty days' personal notice, unless waived by such party, in which to make answers to the petition of the United States; and if such naturalized person be absent from the United States or from the judicial district in which such person last had his residence, such notice shall be given either by personal service upon him or by publication in the manner provided for the service of summons by publication or upon absentees by the laws of the State or the place where such suit is brought."],[0,"(c) Membership in certain organizations; prima facie evidence"],[0,"If a person who shall have been naturalized after December 24, 1952 shall within five years next following such naturalization become a member of or affiliated with any organization, membership in or affiliation with which at the time of naturalization would have precluded such person from naturalization under the provisions of section 1424 of this title, it shall be considered prima facie evidence that such person was not attached to the principles of the Constitution of the United States and was not well disposed to the good order and happiness of the United States at the time of naturalization, and, in the absence of countervailing evidence, it shall be sufficient in the proper proceeding to authorize the revocation and setting aside of the order admitting such person to citizenship and the cancellation of the certificate of naturalization as having been obtained by concealment of a material fact or by willful misrepresentation, and such revocation and setting aside of the order admitting such person to citizenship and such canceling of certificate of naturalization shall be effective as of the original date of the order and certificate, respectively."],[0,"(d) Applicability to citizenship through naturalization of parent or spouse"],[0,"Any person who claims United States citizenship through the naturalization of a parent or spouse in whose case there is a revocation and setting aside of the order admitting such parent or spouse to citizenship under the provisions of subsection (a) of this section on the ground that the order and certificate of naturalization were procured by concealment of a material fact or by willful misrepresentation shall be deemed to have lost and to lose his citizenship and any right or privilege of citizenship which he may have, now has, or may hereafter acquire under and by virtue of such naturalization of such parent or spouse, regardless of whether such person is residing within or without the United States at the time of the revocation and setting aside of the order admitting such parent or spouse to citizenship. Any person who claims United States citizenship through the naturalization of a parent or spouse in whose case there is a revocation and setting aside of the order admitting such parent or spouse to citizenship and the cancellation of the certificate of naturalization under the provisions of subsection (c) of this section, or under the provisions of section 1440(c) of this title on any ground other than that the order and certificate of naturalization were procured by concealment of a material fact or by willful misrepresentation, shall be deemed to have lost and to lose his citizenship and any right or privilege of citizenship which would have been enjoyed by such person had there not been a revocation and setting aside of the order admitting such parent or spouse to citizenship and the cancellation of the certificate of naturalization, unless such person is residing in the United States at the time of the revocation and setting aside of the order admitting such parent or spouse to citizenship and the cancellation of the certificate of naturalization."],[0,"(e) Citizenship unlawfully procured"],[0,"When a person shall be convicted under section 1425 of title 18 of knowingly procuring naturalization in violation of law, the court in which such conviction is had shall thereupon revoke, set aside, and declare void the final order admitting such person to citizenship, and shall declare the certificate of naturalization of such person to be canceled. Jurisdiction is conferred on the courts having jurisdiction of the trial of such offense to make such adjudication."],[0,"(f) Cancellation of certificate of naturalization"],[0,"Whenever an order admitting an alien to citizenship shall be revoked and set aside or a certificate of naturalization shall be canceled, or both, as provided in this section, the court in which such judgment or decree is rendered shall make an order canceling such certificate and shall send a certified copy of such order to the Attorney General. The clerk of court shall transmit a copy of such order and judgment to the Attorney General. A person holding a certificate of naturalization or citizenship which has been canceled as provided by this section shall upon notice by the court by which the decree of cancellation was made, or by the Attorney General, surrender the same to the Attorney General."],[0,"(g) Applicability to certificates of naturalization and citizenship"],[0,"The provisions of this section shall apply not only to any naturalization granted and to certificates of naturalization and citizenship issued under the provisions of this subchapter, but to any naturalization heretofore granted by any court, and to all certificates of naturalization and citizenship which may have been issued heretofore by any court or by the Commissioner based upon naturalization granted by any court, or by a designated representative of the Commissioner under the provisions of section 702 of the Nationality Act of 1940, as amended, or by such designated representative under any other act."],[0,"(h) Power to correct, reopen, alter, modify, or vacate order"],[0,"Nothing contained in this section shall be regarded as limiting, denying, or restricting the power of the Attorney General to correct, reopen, alter, modify, or vacate an order naturalizing the person."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1451?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1451. Revocation of naturalization","tname":"Aliens and Nationality","by":{"0":"","1":""}},{"t":"case","label":"Chaunt v. United States","cite":"364 U.S. 350","y":1960,"id":"1960/22","sc":1,"op":28,"sum":"The Court held that the Government did not meet its standard of proof required under the Immigration and Nationality Act to revoke an order of naturalization.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Schneiderman v. United States","cite":"320 U.S. 118","y":1943,"id":"scdb/1942-045","sc":1,"op":7,"sum":"(1) That the evidence, which is reviewed in the opinion, fails to show with the requisite degree of certainty that during the period in question the defendant was not attached to the principles of the Constitution. P. 135. (2) Attachment to the principles of the Constitution is not necessarily incompatible with a desire to have it amended. P. 137. (3) Utterances of certain leaders of the party organizations in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. Ginsberg","cite":"243 U.S. 472","y":1917,"id":"scdb/1916-136","sc":1,"sum":"When several questions are certified under Jud. Code, § 239, and answers to part will dispose of the case, answers to the rest may be omitted.","sumSrc":"Headnote (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Corrado v. United States","cite":"227 F.2d 780","y":1955,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/227/780/","by":{"1":""}},{"t":"case","label":"United States v. Montalbano","cite":"236 F.2d 757","url":"https://www.courtlistener.com/c/F.2d/236/757/","by":{"1":""}},{"t":"case","label":"Marino v. Murff","cite":"183 F. Supp. 565","y":1959,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./183/565/","by":{"1":""}},{"t":"case","label":"United States v. Chandler","cite":"152 F. Supp. 169","y":1957,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./152/169/","by":{"1":""}},{"t":"case","label":"United States v. Lumantes","cite":"139 F. Supp. 574","y":1955,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./139/574/","by":{"1":""}},{"t":"case","label":"United States v. Oddo","cite":"314 F.2d 115","url":"https://www.courtlistener.com/c/F.2d/314/115/","by":{"1":""}},{"t":"case","label":"United States v. Palciauskas","cite":"734 F.2d 625","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/734/625/","by":{"1":""}},{"t":"case","label":"United States v. Koziy","cite":"728 F.2d 1314","url":"https://www.courtlistener.com/c/F.2d/728/1314/","by":{"1":""}},{"t":"case","label":"Kassab v. INS","cite":"364 F.2d 806","y":1966,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/364/806/","op":1,"by":{"1":""}},{"t":"case","label":"Langhammer v. Hamilton","cite":"295 F.2d 642","y":1961,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/295/642/","op":1,"by":{"1":""}},{"t":"case","label":"La Madrid-Peraza v. INS","cite":"492 F.2d 1297","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/492/1297/","by":{"1":""}},{"t":"case","label":"Berenyi v. District Director","cite":"385 U.S. 630","y":1967,"id":"1966/66","sc":1,"op":1,"sum":"The Court held that it could not review a factual finding by two lower courts without an obvious and exceptional showing of error.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Colautti v. Franklin","cite":"439 U.S. 379","y":1979,"id":"1978/77-891","sc":1,"op":1,"sum":"Section 5 (a) of the Pennsylvania Abortion Control Act requires every person who performs an abortion to make a determination, \"based on his experience, judgment or professional competence,\" that the fetus is not viable. If such person determines that the fetus \"is viable,\" or \"if there is sufficient reason to believe that the fetus may be viable,\" then he must exercise the same care to preserve the fetus' life and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"NLRB v. Amax Coal Co.","cite":"453 U.S. 322","y":1981,"id":"1980/80-289","sc":1,"op":1,"sum":"Employer-selected trustees of a § 302 (c) (5) trust fund are not \"representatives\" of the employer \"for the purposes of collective bargaining or the adjustment of grievances\" within the meaning of § 8 (b) (1) (B). Pp. 328-338. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. Gremillion","cite":"464 F.2d 901","url":"https://www.courtlistener.com/c/F.2d/464/901/","by":{"1":""}},{"t":"case","label":"United States v. Lardieri","cite":"497 F.2d 317","y":1974,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/497/317/","op":1,"by":{"1":""}},{"t":"case","label":"United States v. Ramos","cite":"725 F.2d 1322","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/725/1322/","by":{"1":""}},{"t":"case","label":"United States v. Lopez","cite":"728 F.2d 1359","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/728/1359/","by":{"1":""}},{"t":"case","label":"United States v. Valdez","cite":"594 F.2d 725","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/594/725/","by":{"1":""}},{"t":"case","label":"Tzantarmas v. United States","cite":"402 F.2d 163","y":1968,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/402/163/","by":{"1":""}},{"t":"case","label":"Robles v. United States","cite":"279 F.2d 401","y":1960,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/279/401/","by":{"1":""}},{"t":"case","label":"United States v. Flores-Rodriguez","cite":"237 F.2d 405","y":1956,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/237/405/","by":{"1":""}},{"t":"case","label":"Ventura-Escamilla v. INS","cite":"647 F.2d 28","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/647/28/","by":{"1":""}},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"op":1,"sum":"The Court of Appeals erred in the course of its review of the District Court's judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Tieri v. INS","cite":"457 F.2d 391","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/457/391/","sum":"Upholding denial of naturalization based on pattern of false testimony.","sumSrc":"brief:1","by":{"1":""}},{"t":"case","label":"Ralich v. United States","cite":"185 F.2d 784","y":1950,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/185/784/","sum":"Holding that commission of perjury demonstrates lack of good moral character justifying denial of petition for naturalization.","sumSrc":"brief:1","by":{"1":""}},{"t":"case","label":"United States v. Bramblett","cite":"348 U.S. 503","y":1955,"id":"scdb/1954-048","sc":1,"sum":"The Disbursing Office of the House of Representatives is a \"department or agency\" of the United States within the meaning of 18 U. S. C. § 1001, which forbids the willful falsification of a material fact \"in any matter within the jurisdiction of any department or agency of the United States.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. Wiggan","cite":"673 F.2d 145","url":"https://www.courtlistener.com/c/F.2d/673/145/","by":{"1":""}},{"t":"case","label":"Maikovskis v. INS","cite":"773 F.2d 435","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/773/435/","by":{"1":""}},{"t":"case","label":"McCandless v. United States ex rel. Murphy","cite":"47 F.2d 1072","y":1931,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/47/1072/","by":{"1":""}},{"t":"case","label":"United States v. Shapiro","cite":"43 F. Supp. 927","y":1942,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./43/927/","by":{"1":""}},{"t":"case","label":"United States v. Goldstein","cite":"30 F. Supp. 771","y":1939,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./30/771/","by":{"1":""}},{"t":"case","label":"United States ex rel. Karpay v. Uhl","cite":"70 F.2d 792","url":"https://www.courtlistener.com/c/F.2d/70/792/","by":{"1":""}},{"t":"case","label":"United States v. DeLucia","cite":"256 F.2d 487","url":"https://www.courtlistener.com/c/F.2d/256/487/","by":{"1":""}},{"t":"case","label":"Landon v. Clarke","cite":"239 F.2d 631","y":1956,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/239/631/","by":{"1":""}},{"t":"case","label":"United States v. D'Agostino","cite":"338 F.2d 490","y":1964,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/338/490/","by":{"1":""}},{"t":"case","label":"Johannessen v. United States","cite":"225 U.S. 227","y":1912,"id":"scdb/1911-067","sc":1,"sum":"Prior decisions of this court holding that a judgment of a competent court admitting a person to citizenship is, like every other judgment, competent evidence of its own validity, go no further than protecting the judgment from collateral attack.","sumSrc":"Headnote (U.S. Reports)","by":{"1":""}},{"t":"case","label":"United States v. Riela","cite":"337 F.2d 986","y":1964,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/337/986/","op":1,"by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":""}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","stext":{"head":"§1001. Statements or entries generally","paras":[[0,"(a) Except as otherwise provided in this section, whoever, in any matter within the jurisdiction of the executive, legislative, or judicial branch of the Government of the United States, knowingly and willfully—"],[1,"(1) falsifies, conceals, or covers up by any trick, scheme, or device a material fact;"],[1,"(2) makes any materially false, fictitious, or fraudulent statement or representation; or"],[1,"(3) makes or uses any false writing or document knowing the same to contain any materially false, fictitious, or fraudulent statement or entry;"],[0,"shall be fined under this title, imprisoned not more than 5 years or, if the offense involves international or domestic terrorism (as defined in section 2331), imprisoned not more than 8 years, or both. If the matter relates to an offense under chapter 109A, 109B, 110, or 117, or section 1591, then the term of imprisonment imposed under this section shall be not more than 8 years."],[0,"(b) Subsection (a) does not apply to a party to a judicial proceeding, or that party's counsel, for statements, representations, writings or documents submitted by such party or counsel to a judge or magistrate in that proceeding."],[0,"(c) With respect to any matter within the jurisdiction of the legislative branch, subsection (a) shall apply only to—"],[1,"(1) administrative matters, including a claim for payment, a matter related to the procurement of property or services, personnel or employment practices, or support services, or a document required by law, rule, or regulation to be submitted to the Congress or any office or officer within the legislative branch; or"],[1,"(2) any investigation or review, conducted pursuant to the authority of any committee, subcommittee, commission or office of the Congress, consistent with applicable rules of the House or Senate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1001?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1001. Statements or entries generally","tname":"Crimes and Criminal Procedure","by":{"1":""}},{"t":"usc","label":"18 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/18/1621","stext":{"head":"§1621. Perjury generally","paras":[[0,"Whoever—"],[1,"(1) having taken an oath before a competent tribunal, officer, or person, in any case in which a law of the United States authorizes an oath to be administered, that he will testify, declare, depose, or certify truly, or that any written testimony, declaration, deposition, or certificate by him subscribed, is true, willfully and contrary to such oath states or subscribes any material matter which he does not believe to be true; or"],[1,"(2) in any declaration, certificate, verification, or statement under penalty of perjury as permitted under section 1746 of title 28, United States Code, willfully subscribes as true any material matter which he does not believe to be true;"],[0,"is guilty of perjury and shall, except as otherwise expressly provided by law, be fined under this title or imprisoned not more than five years, or both. This section is applicable whether the statement or subscription is made within or without the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1621. Perjury generally","tname":"Crimes and Criminal Procedure","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(b)"],"by":{"1":""}},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(1)"],"by":{"1":""}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)"],"by":{"1":""}},{"t":"usc","label":"18 U.S.C. § 1623","url":"https://www.law.cornell.edu/uscode/text/18/1623","stext":{"head":"§1623. False declarations before grand jury or court","paras":[[0,"(a) Whoever under oath (or in any declaration, certificate, verification, or statement under penalty of perjury as permitted under section 1746 of title 28, United States Code) in any proceeding before or ancillary to any court or grand jury of the United States knowingly makes any false material declaration or makes or uses any other information, including any book, paper, document, record, recording, or other material, knowing the same to contain any false material declaration, shall be fined under this title or imprisoned not more than five years or, if such proceedings are before or ancillary to the Foreign Intelligence Surveillance Court or the Foreign Intelligence Surveillance Court of Review established by section 103 of the Foreign Intelligence Surveillance Act of 1978 (50 U.S.C. 1803), imprisoned not more than ten years, or both."],[0,"(b) This section is applicable whether the conduct occurred within or without the United States."],[0,"(c) An indictment or information for violation of this section alleging that, in any proceedings before or ancillary to any court or grand jury of the United States, the defendant under oath has knowingly made two or more declarations, which are inconsistent to the degree that one of them is necessarily false, need not specify which declaration is false if—"],[1,"(1) each declaration was material to the point in question, and"],[1,"(2) each declaration was made within the period of the statute of limitations for the offense charged under this section."],[0,"In any prosecution under this section, the falsity of a declaration set forth in the indictment or information shall be established sufficient for conviction by proof that the defendant while under oath made irreconcilably contradictory declarations material to the point in question in any proceeding before or ancillary to any court or grand jury. It shall be a defense to an indictment or information made pursuant to the first sentence of this subsection that the defendant at the time he made each declaration believed the declaration was true."],[0,"(d) Where, in the same continuous court or grand jury proceeding in which a declaration is made, the person making the declaration admits such declaration to be false, such admission shall bar prosecution under this section if, at the time the admission is made, the declaration has not substantially affected the proceeding, or it has not become manifest that such falsity has been or will be exposed."],[0,"(e) Proof beyond a reasonable doubt under this section is sufficient for conviction. It shall not be necessary that such proof be made by any particular number of witnesses or by documentary or other type of evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1623?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1623. False declarations before grand jury or court","tname":"Crimes and Criminal Procedure","by":{"1":""}},{"t":"usc","label":"18 U.S.C. § 1546","url":"https://www.law.cornell.edu/uscode/text/18/1546","by":{"1":""}},{"t":"usc","label":"18 U.S.C. § 1015","url":"https://www.law.cornell.edu/uscode/text/18/1015","subs":["(a)"],"stext":{"head":"§1015. Naturalization, citizenship or alien registry","paras":[[0,"(a) Whoever knowingly makes any false statement under oath, in any case, proceeding, or matter relating to, or under, or by virtue of any law of the United States relating to naturalization, citizenship, or registry of aliens; or"],[0,"(b) Whoever knowingly, with intent to avoid any duty or liability imposed or required by law, denies that he has been naturalized or admitted to be a citizen, after having been so naturalized or admitted; or"],[0,"(c) Whoever uses or attempts to use any certificate of arrival, declaration of intention, certificate of naturalization, certificate of citizenship or other documentary evidence of naturalization or of citizenship, or any duplicate or copy thereof, knowing the same to have been procured by fraud or false evidence or without required appearance or hearing of the applicant in court or otherwise unlawfully obtained; or"],[0,"(d) Whoever knowingly makes any false certificate, acknowledgment or statement concerning the appearance before him or the taking of an oath or affirmation or the signature, attestation or execution by any person with respect to any application, declaration, petition, affidavit, deposition, certificate of naturalization, certificate of citizenship or other paper or writing required or authorized by the laws relating to immigration, naturalization, citizenship, or registry of aliens; or"],[0,"(e) Whoever knowingly makes any false statement or claim that he is, or at any time has been, a citizen or national of the United States, with the intent to obtain on behalf of himself, or any other person, any Federal or State benefit or service, or to engage unlawfully in employment in the United States; or"],[0,"(f) Whoever knowingly makes any false statement or claim that he is a citizen of the United States in order to register to vote or to vote in any Federal, State, or local election (including an initiative, recall, or referendum)—"],[0,"Shall be fined under this title or imprisoned not more than five years, or both. Subsection (f) does not apply to an alien if each natural parent of the alien (or, in the case of an adopted alien, each adoptive parent of the alien) is or was a citizen (whether by birth or naturalization), the alien permanently resided in the United States prior to attaining the age of 16, and the alien reasonably believed at the time of making the false statement or claim that he or she was a citizen of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1015?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1015. Naturalization, citizenship or alien registry","tname":"Crimes and Criminal Procedure","by":{"1":""}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(8)"],"by":{"1":""}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(f)"],"by":{"1":""}}]};